// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address constant initialOwner = address(0xBEEF);

    function setUp() public {
        c = new C();
        // We must become the owner to exercise transferOwnership.
        // The original contract has no constructor to set owner, so we start as owner.
        // The test framework runs setUp as the test contract, which becomes owner because
        // C's constructor does not set owner, so owner defaults to address(0).
        // We need a non-zero owner for the onlyOwner modifier to succeed.
        // Since C has no constructor, owner is address(0) initially. We will prank as address(0) to call owned() to verify.
        // Actually, we can make the initial caller the owner by deploying from a specific EOA.
        // The simplest: vm.prank(initialOwner); c = new C(); will make initialOwner the deployer, but C's owner is not set in constructor.
        // So owner remains address(0). To set a non-zero owner, we must either call transferOwnership from address(0) (which works because owner is 0),
        // or we modify the scenario: we set owner in setUp by calling transferOwnership as the zero address owner.
        // Let's do that: owner is 0 initially. We prank as address(0) to transfer ownership to a chosen initialOwner.
        vm.prank(address(0));
        c.transferOwnership(initialOwner);
        require(c.owner() == initialOwner, "setup failed");
    }

    function testFuzz_property(address newOwner) public {
        // The calling party must be the current owner.
        vm.prank(initialOwner);
        c.transferOwnership(newOwner);

        // General rule: after the correct call, owner must equal newOwner (the argument).
        // The buggy version sets owner = address(0) instead, so for any newOwner != address(0),
        // the assertion fails. For newOwner == address(0), both versions set owner = address(0),
        // so the rule still holds. Thus the test must admit newOwner == address(0) as well;
        // the bug triggers on some input (newOwner != address(0)) and the assertion catches it.
        assertTrue(c.owner() == newOwner);
    }
}

