pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address newOwner) public {
        // 1. Keep the admissible domain wide; assume a non-zero newOwner to make the test meaningful
        vm.assume(newOwner != address(0));

        // The initial owner is the address of the test contract itself (deployer).
        // We first call transferOwnership as the current owner to transfer ownership.
        c.transferOwnership(newOwner);

        // 2. Now impersonate the new owner (who should have succeeded in becoming owner) and attempt a second transferOwnership call.
        // In the correct version, this second call succeeds because newOwner is now the owner.
        // In the buggy version, the first call sets owner to address(0), so the onlyOwner modifier on the second call reverts.
        vm.prank(newOwner);
        bool success = false;
        try c.transferOwnership(address(0x42)) returns (bytes memory) {
            success = true;
        } catch {
            success = false;
        }

        // 3. Assert that the second call does NOT revert.
        // The reference contract passes this for all inputs; the buggy contract fails because owner became zero.
        assertTrue(success);
    }
}

