pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address nonOwner, address initialOwner) public {
        vm.assume(nonOwner != initialOwner);
        vm.assume(nonOwner != address(0));
        vm.assume(initialOwner != address(0));

        // Set up: initialOwner becomes owner
        vm.prank(address(this));
        c.transferOwnership(initialOwner);

        // Check that initial is indeed owner
        require(c.owner() == initialOwner, "setup failed");

        // nonOwner attempts owned()
        vm.prank(nonOwner);
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }

        // The reference C always reverts for a non-owner, so ok must be false.
        // The buggy C with require(true) never reverts, so ok will be true for some input.
        assertTrue(!ok);
    }
}

